function ConsentForm() {
  const [agreed, setAgreed] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    // In a real app, you would send data to a server here
  };

  if (submitted) {
    return (
      <div className="card" role="alert" aria-live="polite">
        <h1>Thank you!</h1>
        <p>Your consent has been recorded.</p>
        <button onClick={() => setSubmitted(false)}>Go back</button>
      </div>
    );
  }

  return (
    <main>
      <div className="card">
        <h1>Welcome</h1>
        <p className="description">Please review and accept our terms to continue.</p>

        <form onSubmit={handleSubmit}>
          <fieldset>
            <legend className="visually-hidden">Consent and Terms</legend>

            <div className="form-field">
              <label className="checkbox-wrapper">
                <input
                  type="checkbox"
                  required
                  checked={agreed}
                  onChange={(e) => setAgreed(e.target.checked)}
                  aria-describedby="consent-helper"
                />
                <div>
                  <span className="label-text">I agree to the Terms of Use</span>
                  <span id="consent-helper" className="helper-text">
                    You must agree to our terms and conditions before proceeding.
                  </span>
                </div>
              </label>
            </div>
          </fieldset>

          <button type="submit">
            Continue
          </button>
        </form>
      </div>
    </main>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ConsentForm />);
